using System;using System.IO;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class PortalPreservePending{
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 edit mode required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_PortalTiles/"));var baseline=JObject.Parse(File.ReadAllText(h+"baseline.json"));string b=(string)baseline["backup"];string pending=Path.Combine(b,"CurrentUserEdit_BeforeTiles.unity");if(File.Exists(pending))throw new Exception("Pending snapshot already exists");bool wasDirty=s.isDirty;if(!EditorSceneManager.SaveScene(s,pending,true))throw new Exception("Pending backup failed");if(!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");File.Copy(s.path,Path.Combine(b,"BaselineImmediatelyBeforeTiles.unity"));baseline["effectiveSceneBackup"]=Path.Combine(b,"BaselineImmediatelyBeforeTiles.unity");baseline["userPendingEditsPreserved"]=wasDirty;File.WriteAllText(h+"baseline.json",baseline.ToString());return new{wasDirty,backup=pending,saved=true,dirty=s.isDirty};}
}
